import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.D5wUhsuj.js";const g=JSON.parse('{"title":"PhyAgentOS 通信架构","description":"","frontmatter":{},"headers":[],"relativePath":"user_development_guide/COMMUNICATION.md","filePath":"user_development_guide/COMMUNICATION.md"}'),o={name:"user_development_guide/COMMUNICATION.md"};function l(s,e,d,r,c,p){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="phyagentos-通信架构" tabindex="-1">PhyAgentOS 通信架构 <a class="header-anchor" href="#phyagentos-通信架构" aria-label="Permalink to &quot;PhyAgentOS 通信架构&quot;">​</a></h1><p><a href="/docs/user_development_guide/COMMUNICATION_en">English</a> · <a href="/docs/">文档索引</a></p><blockquote><p>版本：1.0.0</p></blockquote><h2 id="_1-通信边界" tabindex="-1">1. 通信边界 <a class="header-anchor" href="#_1-通信边界" aria-label="Permalink to &quot;1. 通信边界&quot;">​</a></h2><p>PhyAgentOS 分离六类边界：</p><ol><li>用户/渠道 ↔ AgentLoop 消息；</li><li>Agent tools ↔ AgentTaskCoordinator；</li><li>ForgeToolClient ↔ Gateway Query/Action/Session Tool API；</li><li>observation collector ↔ Gateway 图像/state WebSocket；</li><li>verifier ↔ 独立 Verification Service；</li><li>AgentTask/experience/Runtime ↔ 各自持久化存储。</li></ol><p>边界之间共享不透明 reference，不共享执行所有权。</p><h2 id="_2-用户消息边界" tabindex="-1">2. 用户消息边界 <a class="header-anchor" href="#_2-用户消息边界" aria-label="Permalink to &quot;2. 用户消息边界&quot;">​</a></h2><p>渠道向 Agent bus 发布 <code>InboundMessage</code>。AgentLoop 构造上下文、调用模型与工具，再发送 <code>OutboundMessage</code>。Tool call 遵循注册的 JSON schema。现有文件、目录、Shell、Web、消息、 图片、Scene Graph、Cron、Spawn、Agent Mode、Skill activation 和动态 MCP tools 都使用同一 Loop。</p><p>AgentTask 的 <code>origin_session_key</code> 将 completion experience 关联到原 Agent conversation；它 不是 Gateway execution identifier。</p><h2 id="_3-agenttask-边界" tabindex="-1">3. AgentTask 边界 <a class="header-anchor" href="#_3-agenttask-边界" aria-label="Permalink to &quot;3. AgentTask 边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>forge_task_create</span></span>
<span class="line"><span>forge_task_get</span></span>
<span class="line"><span>forge_task_begin_revision</span></span>
<span class="line"><span>forge_task_finalize</span></span>
<span class="line"><span>forge_task_cancel</span></span></code></pre></div><p>这些 tools 调用 AgentTaskCoordinator，不调用 Dora 或机器人。Coordinator 使用事务 SQLite 限制一个非终态 AgentTask，并保存只追加 PlanRevision、Tool record、evidence reference 与 verification attempt。</p><p>诊断 Query 可不带 <code>task_id</code>；受治理 Query 以及全部 Action/Session 必须带 task。Wrapper 先 检查不可变 Skill/Runtime/ToolSpec binding，再围绕同一 Gateway request 创建或更新匹配 Tool record。这是任务聚合，不是第二条物理执行面。</p><h2 id="_4-gateway-http-边界" tabindex="-1">4. Gateway HTTP 边界 <a class="header-anchor" href="#_4-gateway-http-边界" aria-label="Permalink to &quot;4. Gateway HTTP 边界&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /tools</span></span>
<span class="line"><span>GET  /tools/{tool_id}</span></span>
<span class="line"><span>GET  /tools/{tool_id}/context</span></span>
<span class="line"><span>POST /tools/{endpoint_id}/{operation}:invoke   # Query，HTTP 200</span></span>
<span class="line"><span>POST /tools/{tool_id}:invoke                   # Action/Session admission，HTTP 202</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}</span></span>
<span class="line"><span>GET  /invocations/{invocation_id}/result       # pending 时 HTTP 202</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/cancel</span></span>
<span class="line"><span>POST /invocations/{invocation_id}/stop         # Session</span></span></code></pre></div><p>Query 先读取 ToolSpec，再使用其 <code>endpoint_id</code>、<code>operation</code> 和 <code>semantics=query</code> binding。 Action/Session 根据稳定 Tool ID 调用，两者返回 <code>invocation_id</code>，Action 还返回 <code>attempt_id</code>。</p><p>成功响应必须是 <code>ok=true</code> 且 <code>data</code> 为 object 的 JSON。Error envelope 可以携带 code 与 retryability。Transport timeout 表示远端状态未知。即使后续本地持久化或追踪失败，也必须保留 响应中已返回的 invocation identity。</p><h2 id="_5-identity-边界" tabindex="-1">5. Identity 边界 <a class="header-anchor" href="#_5-identity-边界" aria-label="Permalink to &quot;5. Identity 边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">Namespace</th><th style="text-align:left;">可变性</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS AgentTask</td><td style="text-align:left;">对全部 revisions 稳定</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS Forge binding</td><td style="text-align:left;">不可变 Skill/Runtime/ToolSpec 快照</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS PlanRevision</td><td style="text-align:left;">不可变、只追加规划世代</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS ToolExecutionRecord</td><td style="text-align:left;">不可变 record identity</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS ToolExecutionRecord</td><td style="text-align:left;">异步 admission 前持久化</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway ToolInvocation</td><td style="text-align:left;">稳定 Action/Session 生命周期 identity</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway attempt</td><td style="text-align:left;">对返回的 attempt 稳定</td></tr></tbody></table><p>组件不能从另一个 namespace 派生 identity；关联依赖显式保存的 reference。</p><h2 id="_6-invocation-终态语义" tabindex="-1">6. Invocation 终态语义 <a class="header-anchor" href="#_6-invocation-终态语义" aria-label="Permalink to &quot;6. Invocation 终态语义&quot;">​</a></h2><p>Gateway status/result 是唯一 Action/Session 终态来源。Pending 保持非终态。已知终态包括 Gateway 报告的 success、failure、cancellation 或 stopped。<code>unknown</code> 对 PAOS 记账是终态，因为无法 证明继续进展，但它不是已知物理停止，并继续参与正常 Runtime stop 门控。</p><p>Cancellation/stop <code>requested</code> 或 <code>accepted</code> 只确认控制消息投递，不会取消追踪，也不会直接把 AgentTask 设为 cancelled。PAOS 继续核对并显式 finalize task。</p><h2 id="_7-evidence-websocket-边界" tabindex="-1">7. Evidence WebSocket 边界 <a class="header-anchor" href="#_7-evidence-websocket-边界" aria-label="Permalink to &quot;7. Evidence WebSocket 边界&quot;">​</a></h2><p>PAOS 使用有界连接和采集 timeout 连接配置的图像流与可选 state 流。消息均作为不可信 input。 持久化前校验图像 media、decoded size、sequence、phase、source、本机 receive time 与 SHA-256。</p><p>Collector 在第一次绑定物理执行前和全部 task-owned 执行达到记账终态后采集。Evidence association 为 best-effort；Gateway ToolResult 与 invocation events 仍是权威执行事实。</p><h2 id="_8-verification-边界" tabindex="-1">8. Verification 边界 <a class="header-anchor" href="#_8-verification-边界" aria-label="Permalink to &quot;8. Verification 边界&quot;">​</a></h2><p>Agent-side verifier 把已解析公共任务契约、规范化 Tool facts、evidence、history 和冻结的 scoped Lessons 发送给独立 Verification Service。Lesson 是不可信、非权威建议。Service 不能 调用 Gateway、创建 PlanRevision 或修改 execution record。</p><p>Verifier output 必须通过版本化 verdict contract。AgentTaskCoordinator 应用 <code>off</code>、<code>audit</code>、 <code>enforce</code> 或 <code>recovery</code> 语义并持久化每次 attempt。</p><h2 id="_9-experience-边界" tabindex="-1">9. Experience 边界 <a class="header-anchor" href="#_9-experience-边界" aria-label="Permalink to &quot;9. Experience 边界&quot;">​</a></h2><p>ExperienceCoordinator 接收 AgentTask completion reference。<code>AgentTaskOutcomeSource</code> 构造去敏 envelope，包含 workflow structure、semantic verdict、字段名，以及不透明 task、revision、 invocation、attempt 与 evidence references。原始 arguments、results、凭据、endpoint 和物理 坐标不会复制到学习内容。</p><p>每个 AgentTask 只有一个 episode。PlanRevision、重复 completion notification、review 与 replay 不增加独立支持。</p><h2 id="_10-持久化边界" tabindex="-1">10. 持久化边界 <a class="header-anchor" href="#_10-持久化边界" aria-label="Permalink to &quot;10. 持久化边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Store</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><code>.paos/agent_tasks/tasks.sqlite3</code></td><td style="text-align:left;">AgentTask records 与 append-only events</td></tr><tr><td style="text-align:left;"><code>artifacts/agent_tasks/&lt;task_id&gt;/</code></td><td style="text-align:left;">before/after snapshot、bundle metadata、evidence entity</td></tr><tr><td style="text-align:left;"><code>.paos/evolution/experience.sqlite3</code></td><td style="text-align:left;">binding、episode、Lesson、candidate、job、event</td></tr><tr><td style="text-align:left;">Skill Runtime state path</td><td style="text-align:left;">installed Runtime state、invocation/Session IDs、task bindings 与 audit events</td></tr><tr><td style="text-align:left;">Skill Runtime logs path</td><td style="text-align:left;">生命周期与 Dora launch 日志</td></tr></tbody></table><p>SQLite update 与 artifact write 在各自边界中保持事务或原子。不能因为本地 experience 处理 失败而回滚 Gateway response；evolution fail-open。</p><h2 id="_11-skill-runtime-与-registry-边界" tabindex="-1">11. Skill Runtime 与 Registry 边界 <a class="header-anchor" href="#_11-skill-runtime-与-registry-边界" aria-label="Permalink to &quot;11. Skill Runtime 与 Registry 边界&quot;">​</a></h2><p>Registry/index client 返回 artifact metadata 与下载。Cache/installer 要求 size 与 SHA-256， 随后校验 archive inventory 和精确单可执行文件 Node lock，再原子安装。RuntimeManager 启动命名 Dora flow 并观察 Gateway <code>/tools</code>，不调用另一套 Gateway Agent API。</p><p>活动 Runtime availability provider 向 Agent 提供 Skill visibility 与 Gateway URL，但不修改 AgentTask 或 experience 数据。</p><h2 id="_12-信任规则" tabindex="-1">12. 信任规则 <a class="header-anchor" href="#_12-信任规则" aria-label="Permalink to &quot;12. 信任规则&quot;">​</a></h2><ul><li>ToolSpec、Gateway response、WebSocket payload、task text 与 learned text 都是不可信数据；</li><li>不记录凭据或原始敏感任务 input；</li><li>不从 cancel accepted、timeout 或 unknown 推断停止；</li><li>不绕过 digest 或 archive safety check；</li><li>不在 Agent tools 与 ForgeToolClient 之间增加第二套执行 API；</li><li>Runtime force-stop 与破坏性 artifact cleanup 必须是显式运维动作。</li></ul><h2 id="后续阅读" tabindex="-1">后续阅读 <a class="header-anchor" href="#后续阅读" aria-label="Permalink to &quot;后续阅读&quot;">​</a></h2><ul><li><a href="/docs/user_development_guide/README">集成开发指南</a></li><li><a href="/docs/user_manual/README">运行手册</a></li><li><a href="/docs/forge/README_zh">Forge Tool API 契约</a></li></ul>`,43)])])}const u=t(o,[["render",l]]);export{g as __pageData,u as default};
